/* Table export/import wizard — Navicat-style assistant */
// @ts-nocheck

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ChevronDown, HelpCircle, Loader2 } from 'lucide-react';
import { Modal } from '../../components/ui/Modal';
import { api } from '../../lib/api';
import { notify, notifyError } from '../../lib/notify';

const PROFILE_KEY = 'dbtoolbox_table_exchange_profiles';

const EXPORT_FORMATS = [
  { id: 'txt', label: 'Archivo de texto (*.txt)' },
  { id: 'csv', label: 'Archivo CSV (*.csv)' },
  { id: 'json', label: 'Archivo JSON (*.json)' },
  { id: 'xml', label: 'Archivo XML (*.xml)' },
  { id: 'html', label: 'Archivo HTML (*.htm;*.html)' },
  { id: 'sql', label: 'Archivo de secuencia de comandos SQL (*.sql)' },
  { id: 'xls', label: 'Archivo Excel (*.xls)' },
  { id: 'xlsx', label: 'Archivo de Excel (2007 o posterior) (*.xlsx)' },
  { id: 'dbf', label: 'Archivo BaseD (*.dbf)' },
];

const IMPORT_FORMATS = [
  { id: 'txt', label: 'Archivo de texto (*.txt)' },
  { id: 'csv', label: 'Archivo CSV (*.csv)' },
  { id: 'json', label: 'Archivo JSON (*.json)' },
  { id: 'xml', label: 'Archivo XML (*.xml)' },
  { id: 'xlsx', label: 'Archivo Excel (*.xls; *.xlsx)' },
  { id: 'mdb', label: 'Base de datos MS Access (*.mdb; *.accdb)' },
  { id: 'odbc', label: 'ODBC' },
  { id: 'dbf', label: 'Archivo DBase (*.dbf)' },
  { id: 'db', label: 'Archivo Paradox (*.db)' },
];

function loadProfiles(mode) {
  try {
    const raw = localStorage.getItem(PROFILE_KEY);
    const all = raw ? JSON.parse(raw) : {};
    return all[mode] ?? [];
  } catch {
    return [];
  }
}

function saveProfile(mode, name, data) {
  const raw = localStorage.getItem(PROFILE_KEY);
  const all = raw ? JSON.parse(raw) : {};
  const list = all[mode] ?? [];
  const next = [...list.filter((p) => p.name !== name), { name, ...data }];
  all[mode] = next.slice(-10);
  localStorage.setItem(PROFILE_KEY, JSON.stringify(all));
}

function FormatList({ formats, value, onChange }) {
  return (
    <div className="border border-nv-border rounded bg-nv-bg max-h-64 overflow-y-auto">
      {formats.map((f) => (
        <label
          key={f.id}
          className={`flex items-center gap-2 px-3 py-1.5 cursor-pointer text-xs hover:bg-nv-hover ${value === f.id ? 'bg-nv-accent/10' : ''}`}
        >
          <input type="radio" name="format" checked={value === f.id} onChange={() => onChange(f.id)} />
          <span>{f.label}</span>
        </label>
      ))}
    </div>
  );
}

export function TableExportImportWizard({
  mode,
  connectionId,
  database,
  table,
  onClose,
}) {
  const formats = mode === 'export' ? EXPORT_FORMATS : IMPORT_FORMATS;
  const [step, setStep] = useState(0);
  const [format, setFormat] = useState(formats[0].id);
  const [delimiter, setDelimiter] = useState('\\t');
  const [hasHeader, setHasHeader] = useState(true);
  const [truncate, setTruncate] = useState(false);
  const [busy, setBusy] = useState(false);
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [odbcDsn, setOdbcDsn] = useState('');
  const [odbcUser, setOdbcUser] = useState('');
  const [odbcPassword, setOdbcPassword] = useState('');
  const [odbcQuery, setOdbcQuery] = useState(`SELECT * FROM ${table}`);
  const [profileMenu, setProfileMenu] = useState(false);
  const fileRef = useRef(null);

  const title = mode === 'export' ? 'Asistente de Exportación' : 'Asistente de Importación';
  const intro =
    mode === 'export'
      ? 'El asistente le permite especificar los detalles de cómo exportar sus Datos. ¿Qué formato de exportación desea?'
      : 'Este asistente le permite especificar los detalles sobre cómo importar sus datos. ¿Qué formato de importación de datos desea?';

  const maxStep = mode === 'export' ? 1 : 2;
  const canStart = mode === 'export' ? step === maxStep : step === maxStep && (format === 'odbc' || file);

  useEffect(() => {
    setPreview(null);
  }, [format, file]);

  const buildExportParams = () => {
    const params = new URLSearchParams({ format });
    if (delimiter && (format === 'txt' || format === 'csv')) {
      params.set('delimiter', delimiter === '\\t' ? '\t' : delimiter);
    }
    return params;
  };

  const runExport = async () => {
    setBusy(true);
    try {
      await api.exportTable(connectionId, database, table, buildExportParams());
      notify(`Exportación iniciada: ${table}.${format}`, 'Exportar');
      onClose();
    } catch (e) {
      notifyError(e);
    } finally {
      setBusy(false);
    }
  };

  const buildImportForm = (forPreview = false) => {
    const fd = new FormData();
    let importFormat = format;
    if (file?.name) {
      const ext = file.name.split('.').pop()?.toLowerCase();
      if (ext === 'xls') importFormat = 'xls';
      else if (ext === 'xlsx') importFormat = 'xlsx';
      else if (ext === 'csv') importFormat = 'csv';
      else if (ext === 'json') importFormat = 'json';
      else if (ext === 'xml') importFormat = 'xml';
      else if (ext === 'txt') importFormat = 'txt';
      else if (ext === 'dbf') importFormat = 'dbf';
    }
    fd.append('format', importFormat);
    fd.append('hasHeader', hasHeader ? 'true' : 'false');
    if (delimiter) fd.append('delimiter', delimiter === '\\t' ? '\t' : delimiter);
    if (!forPreview && truncate) fd.append('truncate', 'true');
    if (format === 'odbc') {
      fd.append('odbcDsn', odbcDsn);
      fd.append('odbcUser', odbcUser);
      fd.append('odbcPassword', odbcPassword);
      fd.append('odbcQuery', odbcQuery);
    } else if (file) {
      fd.append('file', file);
    }
    return fd;
  };

  const runPreview = async () => {
    if (format !== 'odbc' && !file) return;
    setBusy(true);
    try {
      const data = await api.previewTableImport(connectionId, database, table, buildImportForm(true));
      setPreview(data);
      setStep(2);
    } catch (e) {
      notifyError(e);
    } finally {
      setBusy(false);
    }
  };

  const runImport = async () => {
    setBusy(true);
    try {
      const result = await api.importTable(connectionId, database, table, buildImportForm(false));
      const errCount = result.errors?.length ?? 0;
      notify(
        `Importación completada: ${result.imported ?? 0} de ${result.total ?? 0} fila(s)` +
          (errCount ? ` (${errCount} error(es))` : ''),
        'Importar',
      );
      onClose();
    } catch (e) {
      notifyError(e);
    } finally {
      setBusy(false);
    }
  };

  const handleStart = () => {
    if (mode === 'export') runExport();
    else runImport();
  };

  const handleNext = () => {
    if (step === 0) setStep(1);
    else if (mode === 'import' && step === 1) runPreview();
  };

  const profileData = useMemo(
    () => ({ format, delimiter, hasHeader, truncate, odbcDsn, odbcUser, odbcQuery }),
    [format, delimiter, hasHeader, truncate, odbcDsn, odbcUser, odbcQuery],
  );

  return (
    <Modal title={title} onClose={onClose} width="max-w-xl">
      <p className="text-xs text-nv-textSubtle mb-3">{intro}</p>
      <div className="text-2xs font-semibold text-nv-textMuted mb-1">
        {mode === 'export' ? 'Exportar formato:' : 'Importar Tipo:'}
      </div>

      {step === 0 && <FormatList formats={formats} value={format} onChange={setFormat} />}

      {step === 1 && (
        <div className="space-y-3 text-xs">
          <div className="text-nv-textSubtle">
            Tabla: <span className="font-mono text-nv-text">{database}.{table}</span>
          </div>
          {(format === 'txt' || format === 'csv') && (
            <label className="block">
              <span className="text-nv-textSubtle text-2xs">Delimitador de campo</span>
              <select className="nv-select w-full mt-0.5" value={delimiter} onChange={(e) => setDelimiter(e.target.value)}>
                <option value="\t">Tabulador</option>
                <option value=",">Coma (,)</option>
                <option value=";">Punto y coma (;)</option>
                <option value="|">Barra vertical (|)</option>
                <option value="auto">Detectar automáticamente</option>
              </select>
            </label>
          )}
          {mode === 'import' && format !== 'odbc' && (
            <>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={hasHeader} onChange={(e) => setHasHeader(e.target.checked)} />
                La primera fila contiene nombres de columna
              </label>
              <label className="block">
                <span className="text-nv-textSubtle text-2xs">Archivo de origen</span>
                <input
                  ref={fileRef}
                  type="file"
                  className="hidden"
                  accept={formatAccept(format)}
                  onChange={(e) => setFile(e.target.files?.[0] ?? null)}
                />
                <div className="flex gap-2 mt-0.5">
                  <button type="button" className="nv-btn" onClick={() => fileRef.current?.click()}>
                    Examinar…
                  </button>
                  <span className="text-2xs text-nv-textMuted self-center truncate">{file?.name ?? 'Ningún archivo seleccionado'}</span>
                </div>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={truncate} onChange={(e) => setTruncate(e.target.checked)} />
                Vaciar tabla antes de importar (TRUNCATE)
              </label>
            </>
          )}
          {mode === 'import' && format === 'odbc' && (
            <div className="space-y-2">
              <label className="block">
                <span className="text-nv-textSubtle text-2xs">DSN ODBC</span>
                <input className="nv-input w-full mt-0.5 font-mono" value={odbcDsn} onChange={(e) => setOdbcDsn(e.target.value)} placeholder="MyDataSource" />
              </label>
              <div className="grid grid-cols-2 gap-2">
                <label className="block">
                  <span className="text-nv-textSubtle text-2xs">Usuario</span>
                  <input className="nv-input w-full mt-0.5" value={odbcUser} onChange={(e) => setOdbcUser(e.target.value)} />
                </label>
                <label className="block">
                  <span className="text-nv-textSubtle text-2xs">Contraseña</span>
                  <input type="password" className="nv-input w-full mt-0.5" value={odbcPassword} onChange={(e) => setOdbcPassword(e.target.value)} />
                </label>
              </div>
              <label className="block">
                <span className="text-nv-textSubtle text-2xs">Consulta SQL</span>
                <textarea className="nv-input w-full mt-0.5 font-mono h-20" value={odbcQuery} onChange={(e) => setOdbcQuery(e.target.value)} />
              </label>
            </div>
          )}
          {mode === 'export' && (
            <p className="text-2xs text-nv-textMuted">
              Se exportarán todos los registros de la tabla actual. Use filtros en la vista de datos para limitar el conjunto.
            </p>
          )}
        </div>
      )}

      {step === 2 && mode === 'import' && preview && (
        <div className="space-y-2 text-xs">
          <p className="text-nv-textSubtle">
            Vista previa: {preview.totalRows} fila(s) detectada(s). Mostrando las primeras {preview.rows?.length ?? 0}.
          </p>
          <div className="border border-nv-border rounded overflow-auto max-h-48">
            <table className="w-full text-2xs">
              <thead className="bg-nv-toolbar sticky top-0">
                <tr>
                  {(preview.columns ?? []).map((c) => (
                    <th key={c} className="px-2 py-1 text-left font-mono border-b border-nv-border">
                      {c}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {(preview.rows ?? []).map((row, i) => (
                  <tr key={i} className="border-b border-nv-border/50">
                    {(preview.columns ?? []).map((c) => (
                      <td key={c} className="px-2 py-0.5 font-mono truncate max-w-[120px]">
                        {row[c] == null ? '' : String(row[c])}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between mt-4 pt-3 border-t border-nv-border">
        <div className="flex items-center gap-1">
          <button type="button" className="nv-btn !p-1" title="Ayuda">
            <HelpCircle size={14} />
          </button>
          <div className="relative">
            <button
              type="button"
              className="nv-btn text-2xs flex items-center gap-1"
              disabled={step === 0}
              onClick={() => setProfileMenu((v) => !v)}
            >
              Guardar Perfil <ChevronDown size={10} />
            </button>
            {profileMenu && (
              <div className="absolute left-0 bottom-full mb-1 z-50 bg-nv-panel border border-nv-border rounded shadow-lg p-2 min-w-[160px]">
                <button
                  type="button"
                  className="nv-btn text-2xs w-full"
                  onClick={() => {
                    const name = window.prompt('Nombre del perfil:');
                    if (name) {
                      saveProfile(mode, name, profileData);
                      notify('Perfil guardado', 'Perfil');
                    }
                    setProfileMenu(false);
                  }}
                >
                  Guardar configuración actual
                </button>
                {loadProfiles(mode).length > 0 && (
                  <div className="mt-2 border-t border-nv-border pt-2 space-y-1">
                    {loadProfiles(mode).map((p) => (
                      <button
                        key={p.name}
                        type="button"
                        className="block w-full text-left text-2xs px-1 py-0.5 hover:bg-nv-hover rounded"
                        onClick={() => {
                          setFormat(p.format ?? format);
                          if (p.delimiter) setDelimiter(p.delimiter);
                          if (p.hasHeader != null) setHasHeader(p.hasHeader);
                          if (p.truncate != null) setTruncate(p.truncate);
                          if (p.odbcDsn) setOdbcDsn(p.odbcDsn);
                          if (p.odbcUser) setOdbcUser(p.odbcUser);
                          if (p.odbcQuery) setOdbcQuery(p.odbcQuery);
                          setProfileMenu(false);
                          notify(`Perfil "${p.name}" cargado`, 'Perfil');
                        }}
                      >
                        {p.name}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" className="nv-btn" disabled={step === 0 || busy} onClick={() => setStep((s) => Math.max(0, s - 1))}>
            Atrás
          </button>
          {step < maxStep ? (
            <button
              type="button"
              className="nv-btn-primary"
              disabled={busy || (step === 1 && mode === 'import' && format !== 'odbc' && !file)}
              onClick={handleNext}
            >
              {busy ? <Loader2 size={12} className="animate-spin inline mr-1" /> : null}
              Siguiente
            </button>
          ) : (
            <button type="button" className="nv-btn-primary" disabled={!canStart || busy} onClick={handleStart}>
              {busy ? <Loader2 size={12} className="animate-spin inline mr-1" /> : null}
              Iniciar
            </button>
          )}
        </div>
      </div>
    </Modal>
  );
}

function formatAccept(format) {
  const map = {
    txt: '.txt,text/plain',
    csv: '.csv,text/csv',
    json: '.json,application/json',
    xml: '.xml,application/xml,text/xml',
    xlsx: '.xls,.xlsx,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    dbf: '.dbf',
    mdb: '.mdb,.accdb',
    db: '.db',
  };
  return map[format] ?? '*/*';
}
